```bash
# Удаляем или исправляем конфигурацию в /etc/nginx/sites-enabled/app
rm /etc/nginx/sites-enabled/app

# Создаем новый конфигурационный файл
cat <<EOF > /etc/nginx/sites-available/app
server {
    listen 8080;
    server_name localhost;

    location / {
        root /srv/www;
        index index.html;
    }
}
EOF

# Создаем символическую ссылку в sites-enabled
ln -s /etc/nginx/sites-available/app /etc/nginx/sites-enabled/

# Проверяем конфигурацию nginx
nginx -t

# Перезапускаем nginx
nginx -s reload
```

